	/* userMapper.checkArchiveNameExistence */
    SELECT EXISTS (
    	SELECT 
    		1
        FROM 
        	USER
        WHERE 
        	ARCHIVE_NAME = #{archiveName}
        	AND USER_UID <> #{userUid}
	) AS FLAG_EXISTENCE

mapper.update:
/* userMapper.updateUser */
UPDATE USER
SET
	USER_NAME 		= #{userName}

		, ARCHIVE_NAME = #{archiveName}
		, ARCHIVE_NAME_UPDATE_DATE = NOW()

	, UPDATE_DATE	= NOW()
	, UPDATE_USER	= #{userUid}

		, PROFILE_IMAGE_UID = #{profileImageUid}


		, PASSWORD = #{password}

WHERE
	USER_UID 		= #{userUid}
	AND FLAG_DELETED = 'N'

		AND BINARY ARCHIVE_NAME <=> BINARY #{previousArchiveName,jdbcType=VARCHAR}
		AND 


		AND PASSWORD = #{currentPasswordHash}

/* userMapper.deleteUser */
UPDATE USER
SET
	FLAG_DELETED = 'Y'
WHERE
	USER_UID = #{userUid}

